<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Bill; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class BillController extends Controller { public function index(){return $this->successResponse(Bill::query()->where('user_id',auth()->id())->orderBy('due_date')->paginate(15));} public function store(Request $r){return $this->successResponse(Bill::create([...$this->data($r),'user_id'=>auth()->id()]),'Bill saved.',201);} public function update(Request $r,int $id){$b=Bill::where('user_id',auth()->id())->findOrFail($id);$b->update($this->data($r,false));return $this->successResponse($b,'Bill updated.');} public function destroy(int $id){Bill::where('user_id',auth()->id())->findOrFail($id)->delete();return $this->successResponse([],'Bill deleted.');} public function markPaid(int $id){$b=Bill::where('user_id',auth()->id())->findOrFail($id);if($b->frequency==='once')$b->update(['paid_at'=>now()]);else {$next=match($b->frequency){'weekly'=>$b->due_date->addWeek(),'monthly'=>$b->due_date->addMonth(),'quarterly'=>$b->due_date->addMonths(3),'yearly'=>$b->due_date->addYear()};$b->update(['due_date'=>$next,'paid_at'=>null]);}return $this->successResponse($b->fresh(),'Bill marked paid.');} private function data(Request $r,bool $required=true):array{$userId=(int)auth()->id();return $r->validate(['name'=>[$required?'required':'sometimes','string','max:160'],'amount'=>[$required?'required':'sometimes','numeric','min:0.01'],'due_date'=>[$required?'required':'sometimes','date'],'frequency'=>[$required?'required':'sometimes','in:weekly,monthly,quarterly,yearly,once'],'account_id'=>['nullable','integer',Rule::exists('accounts','id')->where('user_id',$userId)],'category_id'=>['nullable','integer',Rule::exists('categories','id')->where('user_id',$userId)],'is_active'=>['sometimes','boolean'],'note'=>['nullable','string','max:2000']]);} }
